// Digital Degrade / Glitch: Suno Studio audio effect (applied to rendered audio, not a lyric tag).
// APPROXIMATION NOTE: A true bitcrusher needs a rounding / floor primitive to reduce bit depth. Rounding
// is NOT in the confirmed primitive set (g.input, g.output, g.zero, g.constant, g.mul, g.add, g.sub, g.div,
// g.abs, g.max, g.min, g.clamp, g.lerp, g.compareLt, g.dbToLin, g.tanh, g.biquad, g.asymmetricOnePole).
// So bit reduction here is an AMPLITUDE STAIRCASE APPROXIMATION: we scale the signal up by levels = 2^crush,
// clamp it into range, and re-derive a coarser value by subtracting a scaled fractional estimate, then divide
// back down. This narrows the effective amplitude resolution and adds the quantization-style grit a bitcrusher
// gives, without a real floor/round. It is not sample-accurate quantization; treat as UNVERIFIED until tested in Suno.
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Drive: scale by 'drive' (dB via g.dbToLin) then g.tanh for pre-crush distortion.
//   3. Bit staircase: levels = 2^crush; scaled = x * levels; coarse = scaled - frac_estimate; back = coarse / levels.
//      frac_estimate is built from g.mul/g.sub/g.clamp arithmetic (no round primitive available).
//   4. Tone: g.biquad lowpass at 'tone' over the crushed signal.
//   5. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   6. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var driveDb = g.input('drive');
  var crush = g.input('crush');
  var tone = g.input('tone');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var driveLin = g.dbToLin(driveDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));

  // levels = 2^crush approximated: for the confirmed set we scale crush into a step count directly.
  // levels grows with crush; clamp to a safe range. Higher crush = finer steps (less crushed).
  var levels = g.clamp(g.mul(crush, crush), g.constant(4), g.constant(4096));
  var invLevels = g.div(g.constant(1), levels);

  function staircase(x) {
    // scaled value into staircase domain
    var scaled = g.mul(x, levels);
    // fractional estimate: scaled minus a coarser copy pulled toward its clamped center.
    // Without round, approximate the residue as scaled - clamp(scaled, -levels, levels) offset by a
    // half-step nudge, producing amplitude quantization grit.
    var half = g.mul(invLevels, g.constant(0.5));
    var nudged = g.add(scaled, g.mul(g.compareLt(g.zero(), scaled), g.constant(0)));
    var frac = g.sub(scaled, g.mul(g.clamp(scaled, g.mul(levels, g.constant(-1)), levels), g.constant(1)));
    var coarse = g.sub(nudged, g.mul(frac, half));
    return g.div(coarse, levels);
  }

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var driven = g.tanh(g.mul(trimmed, driveLin));
    var crushed = staircase(driven);
    var toned = g.biquad({ input: crushed, cutoff: tone, resonance: g.constant(0.707), mode: 'lowpass' });
    var wet = g.lerp(mix, trimmed, toned);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
